(function(){
'use strict';
const $=s=>document.querySelector(s), E=POS, KEY='nabta-pos-demo-v1';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=n=>new Intl.NumberFormat('ar-EG',{maximumFractionDigits:3}).format(n);
const money=n=>new Intl.NumberFormat('ar-EG',{minimumFractionDigits:2,maximumFractionDigits:2}).format(n/100);
const date=v=>new Date(v).toLocaleString('ar-EG',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'});
const uid=prefix=>prefix+'-'+Date.now().toString(36).toUpperCase()+'-'+Math.random().toString(36).slice(2,5).toUpperCase();
const stamp=()=>new Date().toISOString();
const cats=['مواد غذائية','ألبان وأجبان','مشروبات','حلويات','عناية وعطور','منظفات'];
const paths={leaf:'M20 4c-9-2-16 3-15 10 1 6 8 7 12 3 3-3 3-8 3-13ZM5 21l10-12',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',cart:'M3 3h2l3 12h10l3-8H6M9 21h.01M18 21h.01',box:'M12 3l9 5v9l-9 5-9-5V8zM3 8l9 5 9-5M12 13v9M7 5l10 5',stock:'M3 21V7l9-4 9 4v14M7 21V11h10v10M7 15h10M7 18h10',truck:'M3 6h12v12H3zM15 10h4l3 4v4h-7M7 21a3 3 0 1 0 0-6 3 3 0 0 0 0 6ZM18 21a3 3 0 1 0 0-6 3 3 0 0 0 0 6Z',users:'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3M9 10a4 4 0 1 0 0-8 4 4 0 0 0 0 8M17 3a4 4 0 0 1 0 8M22 21v-3a4 4 0 0 0-3-4',chart:'M4 3v18h17M8 16v-5M13 16V7M18 16v-9',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18ZM12 7v5l4 2',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14ZM15 15l6 6',plus:'M12 5v14M5 12h14',chevron:'M14 6l-6 6 6 6',download:'M12 3v12M7 10l5 5 5-5M4 16v5h16v-5',receipt:'M5 3h14v18l-3-2-4 2-4-2-3 2zM8 7h8M8 11h8M8 15h4',wallet:'M3 6h17v14H3zM3 6V3h15v3M15 11h7v5h-7z',check:'M5 12l4 4L20 5',warning:'M12 3L2 21h20zM12 9v5M12 17h.01',close:'M6 6l12 12M6 18L18 6',pause:'M8 5v14M16 5v14',card:'M3 5h18v14H3zM3 9h18M6 15h4',scan:'M4 8V4h4M16 4h4v4M20 16v4h-4M8 20H4v-4M8 8v8M11 8v8M14 8v8M17 8v8',edit:'M4 20l4-1L20 7l-4-4L4 15zM14 5l4 4',return:'M9 5L3 11l6 6M3 11h11a6 6 0 0 1 0 12',shield:'M12 3l9 4v6c0 5-9 9-9 9s-9-4-9-9V7zM8 12l3 3 5-6',print:'M6 8V3h12v5M6 17H3V8h18v9h-3M6 13h12v8H6z'};
const icon=(name,size=19)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.box}"/></svg>`;
function art(p){
 const c=p.color||'#87bca6';let shape='';
 if(p.art==='milk')shape=`<path d="M30 14h30l10 13v66H20V27z" fill="${c}"/><path d="M30 14h30l10 13H40z" fill="#ffffff99"/><path d="M30 14L20 27h20z" fill="#ffffff55"/><path d="M20 42h50v29H20z" fill="#ffffffde"/><ellipse cx="45" cy="56" rx="12" ry="7" fill="${c}"/><path d="M26 81h38" stroke="#ffffffbb" stroke-width="3"/>`;
 else if(p.art==='oil'||p.art==='water')shape=`<rect x="36" y="9" width="19" height="13" rx="3" fill="${c}"/><path d="M36 23h19v11c15 8 13 18 13 25v31q0 6-6 6H29q-6 0-6-6V59c0-11-1-17 13-25z" fill="${c}" opacity=".72"/><rect x="24" y="51" width="43" height="27" rx="2" fill="#ffffffe0"/><path d="M36 63h18M32 69h26" stroke="${c}" stroke-width="3"/><path d="M30 43v8M29 82v7" stroke="#ffffffbb" stroke-width="3"/>`;
 else if(p.art==='jar')shape=`<rect x="24" y="13" width="44" height="15" rx="4" fill="#4c3d39"/><rect x="25" y="28" width="42" height="67" rx="9" fill="${c}"/><rect x="25" y="48" width="42" height="30" fill="#f5e7d5"/><ellipse cx="46" cy="63" rx="9" ry="6" fill="#694634"/><path d="M30 35v10" stroke="#ffffff66" stroke-width="3"/>`;
 else if(p.art==='perfume')shape=`<rect x="36" y="12" width="20" height="19" rx="3" fill="#5d5471"/><rect x="40" y="30" width="12" height="10" fill="#d1ba82"/><rect x="20" y="40" width="52" height="54" rx="9" fill="${c}" opacity=".7"/><rect x="28" y="53" width="36" height="25" rx="2" fill="#ffffffe5"/><path d="M38 61h16M35 68h22" stroke="#88729d" stroke-width="2"/><path d="M26 47v39" stroke="#ffffff88" stroke-width="3"/>`;
 else if(p.art==='cheese')shape=`<path d="M16 44l54-18 13 44-53 21z" fill="${c}"/><path d="M16 44l54-18 13 24-54 16z" fill="#fff0c3"/><path d="M29 66l54-16v20L30 91z" fill="#e1bf79"/><g fill="#c49f61"><circle cx="43" cy="75" r="4"/><circle cx="65" cy="67" r="5"/><circle cx="60" cy="80" r="3"/></g>`;
 else if(p.art==='cup')shape=`<path d="M18 43h59L66 91H29z" fill="${c}"/><ellipse cx="47" cy="43" rx="30" ry="9" fill="#f5f9fa"/><ellipse cx="47" cy="41" rx="23" ry="5" fill="#d5e6e5"/><path d="M26 56h43l-4 22H31z" fill="#ffffffe5"/><path d="M38 65h19M35 70h24" stroke="${c}" stroke-width="2"/>`;
 else shape=`<path d="M24 16h44l-3 10 9 64q-26 10-56 0l9-64z" fill="${c}"/><path d="M24 17h44M20 87h52" stroke="#ffffff55" stroke-width="4"/><path d="M25 43h43v31H25z" fill="#ffffffe0"/><path d="M35 51h23M31 58h31M36 65h20" stroke="${c}" stroke-width="3"/><path d="M29 23l-6 60" stroke="#ffffff55" stroke-width="2"/>`;
 return `<svg viewBox="0 0 96 108" aria-hidden="true">${shape}</svg>`;
}
function seed(){let s=createDemoState();[1,2,3,4,5,6,7,8].forEach((v,i)=>{let p=s.products[i%5];s=E.sale(s,[{id:p.id,qty:i+1}],{discount:0,method:i%3?'cash':'card',received:p.price*(i+1),id:'DEMO-'+(1001+i),at:new Date(Date.now()-(7-i)*86400000-3600000).toISOString()}).state;});return s;}
let state,startupWarning='';
try{const raw=localStorage.getItem(KEY);state=raw?JSON.parse(raw):seed();validateBackup(state);}catch(e){state=seed();startupWarning='تعذر قراءة الحفظ المحلي؛ تم فتح بيانات تجريبية جديدة دون استبدال النسخة السابقة.';}
let page='pos',cart=[],discount=0,method='cash',category='الكل',query='',tableQuery='',tableFilter='الكل';
const pages=[['dashboard','نظرة عامة','grid'],['pos','نقطة البيع','cart'],['products','الأصناف','box'],['inventory','المخزون والجرد','stock'],['purchases','المشتريات','truck'],['contacts','العملاء والموردون','users'],['reports','التقارير والأرباح','chart'],['shift','الورديات','clock'],['settings','الإعدادات','settings']];
function commit(next){try{localStorage.setItem(KEY,JSON.stringify(next));state=next;return true;}catch(e){toast('تعذر الحفظ. لم تُنفذ العملية؛ صدّر نسخة من بياناتك.',true);return false;}}
function mutate(fn,event,detail){const next=structuredClone(state);fn(next);if(event)next.audit.unshift({at:stamp(),event,detail});return commit(next);}
function toast(msg,error=false){const t=$('#toast');t.textContent=msg;t.className='show'+(error?' error':'');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.className='',4500);}
function button(label,action,cls='',ico=''){return `<button type="button" class="btn ${cls}" data-action="${action}" ${!label?'aria-label="عن النسخة التجريبية" title="عن النسخة التجريبية"':''}>${ico?icon(ico,17):''}${label}</button>`;}
function empty(message,ico='box'){return `<div class="empty">${icon(ico,34)}<p>${message}</p></div>`;}
function head(title,desc,actions=''){return `<div class="page-head"><div><h1>${title}</h1><p>${desc}</p></div><div class="actions">${actions}</div></div>`;}
function nearExpiry(p){const diff=(new Date(p.expiry+'T23:59:59')-new Date())/86400000;return p.expiry&&diff<=14;}
function stockTag(p){return p.stock===0?'<span class="tag red">نفد المخزون</span>':p.stock<=p.min?'<span class="tag warn">مخزون منخفض</span>':'<span class="tag">متاح</span>';}
function productCell(p){return `<div class="product-cell"><div class="product-thumb">${art(p)}</div><div><b>${esc(p.name)}</b><small>${esc(p.brand)}</small></div></div>`;}
function stats(){const s=E.summary(state);return `<div class="stats">${[['صافي المبيعات',s.revenue,'ج.م','بعد الخصومات والمرتجعات','wallet','featured'],['مجمل الربح',s.grossProfit,'ج.م','المبيعات ناقص تكلفة البضاعة','chart',''],['صافي الربح التقديري',s.netProfit,'ج.م','بعد المصروفات المسجلة فقط','leaf',''],['الفواتير المكتملة',s.count,'فاتورة','كل البيانات التجريبية المسجلة','receipt','']].map(([label,v,unit,note,ico,cls])=>`<div class="panel stat ${cls}"><div class="stat-icon">${icon(ico)}</div><div class="stat-label">${label}</div><div class="stat-value">${unit==='ج.م'?money(v):num(v)} <span>${unit}</span></div><div class="stat-note">${note}</div></div>`).join('')}</div>`;}
function render(){
 const active=pages.find(x=>x[0]===page),low=state.products.filter(p=>p.stock<=p.min).length;
 $('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="logo"><div class="logo-mark">${icon('leaf',27)}</div><div class="brand-text"><div class="brand">نبتة</div><div class="brand-sub">متجرك، في مكان واحد</div></div></div><div class="branch">${icon('stock')}<div><b class="small">${esc(state.store.name)}</b><small class="small">${esc(state.store.branch)}</small></div></div><nav class="nav" aria-label="القائمة الرئيسية"><div class="nav-label">إدارة المتجر</div>${pages.map(([id,label,ico])=>`<button data-page="${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''} title="${label}">${icon(ico)}<span>${label}</span>${id==='inventory'&&low?`<b class="counter">${low}</b>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="user"><div class="avatar">م</div><div class="user-info"><b class="small">${esc(state.shift.cashier)}</b><small>عرض تجريبي • صاحب المتجر</small></div></div></div></aside><div class="workspace"><header class="topbar"><div class="crumb">${esc(state.store.branch)} ${icon('chevron',13)} <b>${active[1]}</b></div><div class="top-tools"><span class="date">${new Date().toLocaleDateString('ar-EG',{weekday:'long',day:'numeric',month:'long'})}</span><span class="demo-label">نسخة تجريبية</span><span class="network"><i class="status-dot"></i>على هذا الجهاز</span>${button('', 'help','icon','warning')}</div></header><main class="content">${({dashboard:dashboard,pos:pos,products:products,inventory:inventory,purchases:purchases,contacts:contacts,reports:reports,shift:shift,settings:settings})[page]()}<footer class="footer"><span>نبتة ١٫٠ • بيانات تجريبية محفوظة في هذا المتصفح</span><span>${esc(state.shift.till)} • ${state.shift.open?'الوردية مفتوحة':'الوردية مغلقة'} • الأسعار بالجنيه المصري</span></footer></main></div></div>`;
 if(page==='pos')renderCatalog();
}
function dashboard(){
 const low=state.products.filter(p=>p.stock<=p.min),soon=state.products.filter(nearExpiry);
 const days=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);const total=state.sales.filter(s=>!s.returned&&new Date(s.at).toDateString()===d.toDateString()).reduce((a,s)=>a+s.total,0);return {name:d.toLocaleDateString('ar-EG',{weekday:'short'}),total};});const max=Math.max(1,...days.map(d=>d.total));
 return head('كل التفاصيل، في نظرة واحدة','تابع حركة متجرك واتخذ القرار على أساس الأرقام.',button('بدء البيع','goto-pos','primary','cart'))+stats()+`<div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><h2>حركة المبيعات</h2><small>صافي مبيعات آخر ٧ أيام</small></div><span class="tag">من الفواتير المسجلة</span></div><div class="chart">${days.map((d,i)=>`<div class="bar ${i===6?'current':''}" style="height:${Math.max(3,d.total/max*100)}%" title="${money(d.total)} ج.م"><span>${d.name}</span></div>`).join('')}</div><div class="chart-note">الإجمالي: ${money(days.reduce((a,d)=>a+d.total,0))} ج.م</div></section><section class="panel"><div class="panel-head"><div><h2>يحتاج انتباهك</h2><small>خطوة صغيرة تحافظ على المخزون</small></div>${icon('warning')}</div><div class="alerts"><div class="alert-row"><div class="alert-icon">${icon('box')}</div><div><p>${num(low.length)} أصناف بمخزون منخفض</p><small>راجع حد إعادة الطلب</small></div>${button('مراجعة','goto-inventory')}</div><div class="alert-row"><div class="alert-icon">${icon('clock')}</div><div><p>${num(soon.length)} أصناف قرب انتهاء الصلاحية</p><small>الصلاحية خلال ١٤ يومًا أو أقل</small></div>${button('مراجعة','expiry-filter')}</div><div class="alert-row"><div class="alert-icon" style="background:var(--soft);color:var(--green)">${icon('wallet')}</div><div><p>النقدية المتوقعة ${money(E.expectedCash(state))} ج.م</p><small>قارنها بالعد الفعلي عند الإغلاق</small></div>${button('الوردية','goto-shift')}</div></div></section></div>`+salesPanel(5);
}
function pos(){return head('نقطة البيع','ابحث، امسح الباركود، وأكمل الفاتورة في خطوات بسيطة.',button('الفواتير المعلقة <span class="tag">'+num(state.held.length)+'</span>','held','','pause'))+`<div class="pos-layout"><section class="pos-catalog"><div class="search-box">${icon('scan')}<input id="pos-search" aria-label="بحث بالأصناف أو الباركود" autocomplete="off" placeholder="ابحث باسم الصنف أو امسح الباركود…  F2" value="${esc(query)}"></div><div class="tabs" role="group" aria-label="تصنيف المنتجات">${['الكل',...cats].map(c=>`<button data-category="${c}" class="${category===c?'selected':''}">${c}</button>`).join('')}</div><div id="catalog" class="products-grid"></div><div class="health-strip">${icon('scan')}<span>ماسح USB الذي يكتب كلوحة مفاتيح: ضع المؤشر في البحث ثم امسح.<br><small>للتجربة: <span class="ltr">6221000000011</span> ثم Enter.</small></span></div></section><aside id="cart" class="panel cart">${cartView()}</aside></div><div class="keyboard-hint"><kbd>F2</kbd> البحث &nbsp; <kbd>F4</kbd> الدفع &nbsp; <kbd>F8</kbd> تعليق الفاتورة &nbsp; <kbd>Esc</kbd> إغلاق النافذة</div>`;}
function renderCatalog(){if(!$('#catalog'))return;const list=state.products.filter(p=>(category==='الكل'||p.category===category)&&(!query||[p.name,p.brand,p.barcode].some(v=>v.toLowerCase().includes(query.toLowerCase()))));$('#catalog').innerHTML=list.length?list.map(p=>`<button class="product-card" data-add="${p.id}" ${p.stock===0?'disabled':''} aria-label="إضافة ${esc(p.name)}"><span class="stock-badge ${p.stock<=p.min?'low':''}">${num(p.stock)} ${p.unit}</span><div class="art" style="--art-bg:${p.color}13">${art(p)}</div><h3>${esc(p.name)}</h3><small>${esc(p.brand)}</small><div class="card-bottom"><span>${money(p.price)} <small>ج.م${p.unit==='كجم'?' / كجم':''}</small></span><span class="card-plus">${icon('plus',15)}</span></div></button>`).join(''):empty('لا توجد أصناف مطابقة. غيّر البحث أو أضف صنفًا.','search');}
function cartView(){let t;try{t=E.totals(cart,discount);}catch{t=E.totals(cart);discount=0;}
 return `<div class="cart-head"><div><h2>الفاتورة الحالية</h2><small>بيع مباشر • ${esc(state.shift.till)}</small></div><span class="tag">${num(cart.length)} أصناف</span></div><div class="cart-lines">${cart.length?cart.map(l=>`<div class="cart-line"><div class="cart-line-top"><b>${esc(l.name)}</b><button class="remove" data-remove="${l.id}" aria-label="حذف ${esc(l.name)}">${icon('close',14)}</button></div><div class="cart-line-bottom"><div class="quantity"><button data-qty="${l.id}" data-delta="-1" aria-label="تقليل الكمية">−</button><button data-weight="${l.id}" title="تغيير الكمية">${num(l.qty)}</button><button data-qty="${l.id}" data-delta="1" aria-label="زيادة الكمية">+</button></div><span class="small">${money(E.amount(l.price,l.qty))} ج.م</span></div></div>`).join(''):empty('الفاتورة جاهزة. أضف أول صنف من القائمة.','cart')}</div><div class="cart-summary"><div class="sum-row"><span class="muted">إجمالي الأصناف</span><span>${money(t.subtotal)} ج.م</span></div><div class="sum-row"><label for="discount">خصم الفاتورة (ج.م)</label><input id="discount" class="discount-input" type="number" min="0" max="${t.subtotal/100}" step=".01" value="${discount/100}"></div><div class="sum-row total"><span>المطلوب دفعه</span><div><strong>${money(t.total)}</strong> <small>ج.م</small></div></div><div class="payment-tabs"><button data-method="cash" class="${method==='cash'?'active':''}">${icon('wallet',16)} نقدي</button><button data-method="card" class="${method==='card'?'active':''}">${icon('card',16)} بطاقة</button></div><button class="btn primary checkout" data-action="pay" ${cart.length&&state.shift.open?'':'disabled'}>${icon('check',19)} إتمام البيع <span style="margin-right:auto;opacity:.6">F4</span></button>${!state.shift.open?'<p class="help" style="margin-top:10px;color:var(--red)">الوردية مغلقة. افتح وردية لبدء البيع.</p>':''}</div><div class="cart-secondary">${button('تعليق','hold','','pause')}${button('إفراغ','clear','','close')}</div>`;
}
function renderCart(){if($('#cart'))$('#cart').innerHTML=cartView();}
function add(id,qty=1){const p=state.products.find(p=>p.id===id),line=cart.find(l=>l.id===id);if(!p)return;const next=E.quantity((line?.qty||0)+qty);if(next<=0||next>p.stock){toast('المخزون غير كافٍ لهذا الصنف.',true);return;}if(line)line.qty=next;else cart.push({id:p.id,name:p.name,unit:p.unit,price:p.price,cost:p.cost,qty});renderCart();}
function searchToolbar(placeholder,filters){return `<div class="toolbar"><div class="search-box">${icon('search')}<input id="table-search" placeholder="${placeholder}" aria-label="${placeholder}" value="${esc(tableQuery)}"></div>${filters?`<select id="table-filter" aria-label="تصفية القائمة">${filters.map(c=>`<option ${tableFilter===c?'selected':''}>${c}</option>`).join('')}</select>`:''}</div>`;}
function products(){return head('دليل الأصناف','كل منتج، وسعره، وباركوده في قائمة واحدة.',button('تصدير CSV','export-products','','download')+button('إضافة صنف','add-product','primary','plus'))+`<section class="panel">${searchToolbar('ابحث بالاسم أو الباركود',['الكل',...cats])}<div id="table-results">${productTable()}</div></section>`;}
function filteredProducts(){return state.products.filter(p=>(tableFilter==='الكل'||p.category===tableFilter||tableFilter==='مخزون منخفض'&&p.stock<=p.min||tableFilter==='قرب الصلاحية'&&nearExpiry(p))&&[p.name,p.barcode,p.brand].some(v=>v.toLowerCase().includes(tableQuery.toLowerCase())));}
function productTable(){const list=filteredProducts();return `<div class="table-wrap"><table><thead><tr><th>الصنف</th><th>الباركود</th><th>التصنيف</th><th>سعر البيع</th><th>التكلفة الحالية</th><th>المخزون</th><th>الحالة</th><th></th></tr></thead><tbody>${list.map(p=>`<tr><td>${productCell(p)}</td><td><span class="ltr muted small">${esc(p.barcode)}</span></td><td>${esc(p.category)}</td><td><b>${money(p.price)}</b></td><td>${money(p.cost)}</td><td>${num(p.stock)} ${p.unit}</td><td>${stockTag(p)}</td><td><button class="btn icon" data-edit="${p.id}" aria-label="تعديل ${esc(p.name)}">${icon('edit',16)}</button></td></tr>`).join('')}</tbody></table>${!list.length?empty('لا توجد أصناف مطابقة.'):''}</div>`;}
function inventory(){const value=state.products.reduce((a,p)=>a+E.amount(p.cost,p.stock),0);return head('المخزون والجرد','تتبّع النواقص والصلاحية وسجّل فروق العد الفعلي.',button('تسجيل جرد','adjust','primary','stock'))+`<div class="stats"><div class="panel stat"><div class="stat-label">قيمة المخزون بالتكلفة الحالية</div><div class="stat-value">${money(value)} <span>ج.م</span></div></div><div class="panel stat"><div class="stat-label">إجمالي الأصناف</div><div class="stat-value">${num(state.products.length)} <span>صنف</span></div></div><div class="panel stat"><div class="stat-label">أقل من حد إعادة الطلب</div><div class="stat-value">${num(state.products.filter(p=>p.stock<=p.min).length)} <span>صنف</span></div></div><div class="panel stat"><div class="stat-label">خلال ١٤ يومًا أو منتهية</div><div class="stat-value">${num(state.products.filter(nearExpiry).length)} <span>صنف</span></div></div></div><section class="panel">${searchToolbar('ابحث عن صنف للجرد',['الكل','مخزون منخفض','قرب الصلاحية'])}<div id="table-results">${inventoryTable()}</div></section><p class="overview-caption">هذه التجربة تتعامل مع تاريخ صلاحية واحد للصنف. إدارة الدفعات والتكلفة المرجحة وفروق الجرد ضمن خطة النظام الكامل.</p>`;}
function inventoryTable(){return `<div class="table-wrap"><table><thead><tr><th>الصنف</th><th>المتاح</th><th>حد الطلب</th><th>الصلاحية</th><th>حالة المخزون</th><th></th></tr></thead><tbody>${filteredProducts().map(p=>`<tr><td>${productCell(p)}</td><td><b>${num(p.stock)}</b> ${p.unit}</td><td>${num(p.min)}</td><td>${p.expiry?`<span class="tag ${nearExpiry(p)?'warn':''}">${esc(p.expiry)}</span>`:'غير محددة'}</td><td>${stockTag(p)}</td><td><button class="btn" data-adjust="${p.id}">جرد الصنف</button></td></tr>`).join('')}</tbody></table>${!filteredProducts().length?empty('لا توجد أصناف مطابقة.'):''}</div>`;}
function purchases(){return head('المشتريات','سجّل استلام البضاعة لتحديث رصيد المخزون.',button('استلام بضاعة','purchase','primary','plus'))+`<div class="callout">الاستلام التجريبي لصنف واحد في كل عملية. الاستلام متعدد الأصناف وحسابات الموردين ضمن خطة التنفيذ.</div><section class="panel"><div class="panel-head"><h2>سجل الاستلام</h2><span class="tag">${num(state.purchases.length)} عملية</span></div><div class="table-wrap"><table><thead><tr><th>رقم العملية</th><th>التاريخ</th><th>المورد</th><th>الصنف</th><th>الكمية</th><th>التكلفة الإجمالية</th></tr></thead><tbody>${[...state.purchases].reverse().map(p=>`<tr><td>${esc(p.id)}</td><td>${date(p.at)}</td><td>${esc(p.supplier)}</td><td>${esc(p.name)}</td><td>${num(p.qty)}</td><td>${money(p.total)} ج.م</td></tr>`).join('')}</tbody></table>${!state.purchases.length?empty('لم تسجّل مشتريات بعد. ابدأ باستلام بضاعة من المورد.','truck'):''}</div></section>`;}
function contacts(){return head('العملاء والموردون','دليل بسيط للتواصل مع شركاء متجرك.',button('إضافة جهة','contact','primary','plus'))+`<section class="panel">${searchToolbar('ابحث عن اسم أو رقم هاتف',['الكل','عميل','مورد'])}<div id="table-results">${contactsTable()}</div></section>`;}
function contactsTable(){const list=state.contacts.filter(c=>(tableFilter==='الكل'||c.type===tableFilter)&&[c.name,c.phone].some(v=>v.includes(tableQuery)));return `<div class="table-wrap"><table><thead><tr><th>الاسم</th><th>النوع</th><th>الهاتف</th></tr></thead><tbody>${list.map(c=>`<tr><td><b>${esc(c.name)}</b></td><td><span class="tag ${c.type==='مورد'?'blue':''}">${c.type}</span></td><td><span class="ltr">${esc(c.phone)||'—'}</span></td></tr>`).join('')}</tbody></table>${!list.length?empty('لا توجد جهات مطابقة.','users'):''}</div>`;}
function salesPanel(limit=0){const list=[...state.sales].reverse().slice(0,limit||state.sales.length);return `<section class="panel"><div class="panel-head"><div><h2>الفواتير ${limit?'الأخيرة':'والمرتجعات'}</h2><small>اضغط على الفاتورة لعرضها أو طباعتها</small></div>${limit?button('كل الفواتير','goto-reports'):button('تصدير CSV','export-sales','','download')}</div><div class="table-wrap"><table><thead><tr><th>رقم الفاتورة</th><th>التاريخ</th><th>عدد الأصناف</th><th>الدفع</th><th>الإجمالي</th><th>الحالة</th><th></th></tr></thead><tbody>${list.map(s=>`<tr><td><button data-receipt="${s.id}" style="color:var(--green);font-weight:bold">${esc(s.id)}</button></td><td>${date(s.at)}</td><td>${num(s.lines.length)}</td><td>${s.method==='cash'?'نقدي':'بطاقة'}</td><td><b>${money(s.total)}</b> ج.م</td><td><span class="tag ${s.returned?'red':''}">${s.returned?'مرتجعة':'مكتملة'}</span></td><td>${!s.returned?`<button class="btn icon" data-refund="${s.id}" aria-label="إرجاع الفاتورة ${esc(s.id)}" title="مرتجع كامل">${icon('return',16)}</button>`:''}</td></tr>`).join('')}</tbody></table>${!list.length?empty('لا توجد فواتير بعد.','receipt'):''}</div></section>`;}
function reports(){const s=E.summary(state);return head('الأرقام تحكي قصة متجرك','تقارير مستخرجة من العمليات التجريبية، بدون أرقام تقديرية للمبيعات.',button('تسجيل مصروف','expense','primary','plus'))+stats()+`<div class="split" style="margin-bottom:20px"><section class="panel"><div class="panel-head"><h2>تفاصيل الربح</h2><span class="tag">كل الفترة</span></div><div class="panel-body">${[['صافي المبيعات',s.revenue],['تكلفة البضاعة المباعة',s.cogs],['مجمل الربح',s.grossProfit],['المصروفات المسجلة',s.expenses],['صافي الربح التقديري',s.netProfit]].map(([k,v])=>`<div class="list-row"><span>${k}</span><b>${money(v)} ج.م</b></div>`).join('')}<p class="overview-caption">التكلفة في هذه التجربة تؤخذ من سعر التكلفة الحالي عند البيع. الضرائب والإهلاك وخسائر الجرد غير محسوبة هنا.</p></div></section><section class="panel"><div class="panel-head"><h2>المصروفات</h2><span class="tag">${num(state.expenses.length)} مصروف</span></div><div class="panel-body">${state.expenses.length?[...state.expenses].reverse().map(e=>`<div class="list-row"><div><p>${esc(e.name)}</p><small>${date(e.at)} • نقدي من الدرج</small></div><b>${money(e.amount)} ج.م</b></div>`).join(''):empty('أضف مصروفًا لعرض الربح بعد المصروفات.','wallet')}</div></section></div>`+salesPanel();}
function shift(){const cash=E.expectedCash(state);return head('إدارة الوردية','راجع رصيد الدرج، وسجّل الفرق عند إغلاق الوردية.',button(state.shift.open?'إغلاق الوردية':'فتح وردية',state.shift.open?'close-shift':'open-shift','primary','clock'))+`<div class="split"><section class="panel"><div class="panel-head"><h2>${esc(state.shift.till)}</h2><span class="tag ${state.shift.open?'':'warn'}">${state.shift.open?'مفتوحة':'مغلقة'}</span></div><div class="panel-body"><p class="muted small">النقدية المتوقعة في الدرج</p><div class="big-number">${money(cash)} <span class="small">ج.م</span></div><div class="list-row"><span>رصيد الافتتاح</span><b>${money(state.shift.opening)} ج.م</b></div><div class="list-row"><span>الكاشير</span><b>${esc(state.shift.cashier)}</b></div><div class="list-row"><span>بداية الوردية</span><b class="small">${date(state.shift.startedAt)}</b></div><div class="switch-note">المتوقع = رصيد الافتتاح + مبيعات النقدي − مرتجعات النقدي المنفذة في الوردية − المصروفات النقدية.</div></div></section><section class="panel"><div class="panel-head"><h2>الورديات السابقة</h2></div><div class="panel-body">${state.shiftHistory.length?[...state.shiftHistory].reverse().map(s=>`<div class="list-row"><div><p>${esc(s.cashier)} • ${esc(s.till)}</p><small>${date(s.closedAt)}</small></div><div style="text-align:left"><b>${money(s.actual)} ج.م</b><br><span class="tag ${s.difference?'warn':''}">الفرق ${money(s.difference)}</span></div></div>`).join(''):empty('لم تُغلق أي وردية في هذه التجربة.','clock')}</div></section></div><section class="panel" style="margin-top:20px"><div class="panel-head"><h2>سجل العمليات</h2><small>آخر ٢٠ عملية</small></div><div class="table-wrap"><table><thead><tr><th>التاريخ</th><th>العملية</th><th>التفاصيل</th></tr></thead><tbody>${state.audit.slice(0,20).map(a=>`<tr><td>${date(a.at)}</td><td>${esc(a.event)}</td><td>${esc(a.detail)}</td></tr>`).join('')}</tbody></table></div></section>`;}
function settings(){return head('الإعدادات','بيانات متجرك ونسخ بيانات التجربة.')+`<div class="split"><section class="panel"><div class="panel-head"><h2>بيانات المتجر والفاتورة</h2></div><form id="settings-form" class="panel-body"><div class="info-grid">${field('اسم المتجر','name','text',state.store.name,true)}${field('اسم الفرع','branch','text',state.store.branch,true)}${field('العنوان','address','text',state.store.address)}${field('رقم الهاتف','phone','text',state.store.phone)}<label class="field full">رسالة أسفل الفاتورة<input name="receiptNote" value="${esc(state.store.receiptNote)}" maxlength="150"></label></div><div style="margin-top:20px">${button('حفظ البيانات','save-settings','primary','check')}</div></form></section><section class="panel"><div class="panel-head"><h2>بيانات التجربة</h2>${icon('shield')}</div><div class="panel-body"><div class="callout warn">الحفظ داخل المتصفح فقط. هذه النسخة ليست نظام تشغيل تجاري ولا تربط أجهزة الكاشير ببعضها.</div><div class="list-row"><div><p>نسخة من البيانات</p><small>تنزيل ملف JSON كامل للتجربة</small></div>${button('تصدير','backup','','download')}</div><div class="list-row"><div><p>استعادة نسخة تجريبية</p><small>يستبدل بيانات هذا المتصفح بعد التأكيد</small></div>${button('استيراد','restore')}</div><div class="list-row"><div><p>العودة للبيانات الأصلية</p><small>يحذف تعديلات التجربة فقط</small></div>${button('إعادة ضبط','reset','danger')}</div><div class="app-info">بدون اتصالات خارجية أو اشتراكات داخل الواجهة. الربط بالطابعة والصلاحيات وقاعدة البيانات من مهام كوديكس.</div></div></section></div>`;}
function field(label,name,type='text',value='',required=false,extra=''){return `<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${extra}></label>`;}
function selectField(label,name,options,value=''){return `<label class="field">${label}<select name="${name}">${options.map(o=>typeof o==='string'?`<option ${o===value?'selected':''}>${esc(o)}</option>`:`<option value="${esc(o.id)}" ${o.id===value?'selected':''}>${esc(o.name)}</option>`).join('')}</select></label>`;}
function show(title,body,submit,handler){$('#modal-content').innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="btn icon" data-action="close-modal" aria-label="إغلاق">${icon('close')}</button></div><form id="modal-form"><div class="modal-body">${body}<div class="form-error" id="form-error" role="alert"></div></div><div class="modal-footer">${button('إلغاء','close-modal')}<button type="submit" class="btn primary">${submit}</button></div></form>`;$('#modal-form').onsubmit=e=>{e.preventDefault();if(!e.currentTarget.reportValidity())return;try{handler(new FormData(e.currentTarget));}catch(err){$('#form-error').textContent=err.message;}};$('#modal').showModal();}
function close(){ $('#modal').close();document.body.classList.remove('printing-receipt');}
function cents(v){const n=Number(v);if(!Number.isFinite(n)||n<0||n>100000000)throw Error('أدخل مبلغًا صحيحًا أكبر من أو يساوي صفرًا');return Math.round(n*100);}
function qty(v,p){const n=E.quantity(v);if(!Number.isFinite(n)||n<=0||(p.unit==='قطعة'&&!Number.isInteger(n)))throw Error('أدخل كمية موجبة؛ أصناف القطعة لا تقبل كسورًا');return n;}
function refresh(){close();render();}
function productForm(id){const p=state.products.find(p=>p.id===id);show(p?'تعديل الصنف':'إضافة صنف جديد',`<div class="info-grid">${field('اسم الصنف','name','text',p?.name||'',true,'maxlength="80"')}${field('وصف العبوة أو العلامة','brand','text',p?.brand||'',false,'maxlength="80"')}${field('الباركود','barcode','text',p?.barcode||'',true,'maxlength="40"')}${selectField('التصنيف','category',cats,p?.category||cats[0])}${selectField('وحدة البيع','unit',['قطعة','كجم'],p?.unit||'قطعة')}${field('سعر البيع (ج.م)','price','number',(p?.price||0)/100,true,'min="0.01" step=".01"')}${field('التكلفة الحالية (ج.م)','cost','number',(p?.cost||0)/100,true,'min="0" step=".01"')}${field('حد إعادة الطلب','min','number',p?.min||0,true,'min="0" step=".001"')}${!p?field('مخزون افتتاحي','stock','number',0,true,'min="0" step=".001"'):''}${field('تاريخ الصلاحية','expiry','date',p?.expiry||'')}</div>${p?'<p class="help" style="margin-top:15px">لتغيير المخزون استخدم الجرد أو استلام البضاعة.</p>':''}`,'حفظ الصنف',f=>{const name=f.get('name').trim(),barcode=f.get('barcode').trim(),unit=f.get('unit');if(!name||!barcode)throw Error('اسم الصنف والباركود مطلوبان');if(state.products.some(x=>x.barcode===barcode&&x.id!==id))throw Error('هذا الباركود مستخدم لصنف آخر');const price=cents(f.get('price')),cost=cents(f.get('cost')),min=E.quantity(f.get('min'));const stock=p?p.stock:E.quantity(f.get('stock'));if(price<=0||!Number.isFinite(min)||min<0||!Number.isFinite(stock)||stock<0)throw Error('راجع السعر والكميات');if(unit==='قطعة'&&(!Number.isInteger(stock)||!Number.isInteger(min)))throw Error('أصناف القطعة لا تقبل مخزونًا أو حد طلب بكسور');if(p&&p.unit!==unit&&(cart.some(l=>l.id===id)||state.sales.some(s=>s.lines.some(l=>l.id===id))||state.held.some(h=>h.lines.some(l=>l.id===id))))throw Error('لا تغيّر وحدة صنف له عمليات؛ أضف صنفًا جديدًا');const item={id:id||uid('P'),name,barcode,brand:f.get('brand').trim(),category:f.get('category'),unit,price,cost,stock,min,expiry:f.get('expiry'),art:p?.art||'bag',color:p?.color||'#87bca6'};if(mutate(s=>{if(p)s.products[s.products.findIndex(x=>x.id===id)]=item;else s.products.push(item);},p?'تعديل صنف':'إضافة صنف',name)){cart=cart.map(l=>l.id===id?{...l,name,unit,price,cost}:l);refresh();toast('تم حفظ الصنف');}});}
function changeQuantity(id){const p=state.products.find(p=>p.id===id),line=cart.find(l=>l.id===id);show('كمية الصنف',`<p class="modal-desc">${esc(p.name)} • ${money(p.price)} ج.م / ${p.unit}</p>${field('الكمية ('+p.unit+')','qty','number',line?.qty||1,true,`min="${p.unit==='كجم'?'.001':'1'}" step="${p.unit==='كجم'?'.001':'1'}" max="${p.stock}"`)}`,'تحديث الكمية',f=>{const n=qty(f.get('qty'),p);if(n>p.stock)throw Error('الكمية أكبر من المخزون');if(line)line.qty=n;else add(id,n);close();renderCart();});}
function pay(){if(!cart.length){toast('أضف صنفًا أولًا',true);return;}if(!state.shift.open){toast('افتح وردية أولًا',true);return;}let t;try{E.validateLines(state.products,cart);t=E.totals(cart,discount);}catch(e){toast(e.message,true);return;}show('إتمام البيع',`<div class="callout"><div class="sum-row"><span>المطلوب</span><b>${money(t.total)} ج.م</b></div><div class="help">${method==='cash'?'الدفع النقدي — أدخل المبلغ المستلم لحساب الباقي':'بطاقة — تسجيل وسيلة الدفع فقط، لا توجد عملية خصم بنكية في التجربة'}</div></div>${method==='cash'?field('المبلغ المستلم (ج.م)','received','number',t.total/100,true,`min="${t.total/100}" step=".01"`):'<p class="modal-desc">تأكد من نجاح الدفع على جهاز البنك قبل تسجيل الفاتورة.</p>'}<div id="change-preview" class="help"></div>`,'تأكيد وتسجيل الفاتورة',f=>{const result=E.sale(state,cart,{discount,method,received:method==='cash'?cents(f.get('received')):t.total,id:uid('INV'),at:stamp()});if(commit(result.state)){cart=[];discount=0;close();render();receipt(result.invoice.id);toast('تم البيع • الباقي '+money(result.change)+' ج.م');}});const input=$('#modal input[name=received]');if(input){input.addEventListener('input',()=>{$('#change-preview').textContent='الباقي: '+money(Math.max(0,Math.round(Number(input.value)*100)-t.total))+' ج.م';});input.select();}}
function receipt(id){const s=state.sales.find(s=>s.id===id);if(!s)return;show('الفاتورة',`<div class="receipt"><div class="receipt-heading"><h2>${esc(state.store.name)}</h2><small>${esc(state.store.branch)} • ${esc(state.store.address)}</small><small>${esc(state.store.phone)}</small><p style="margin-top:10px">${esc(s.id)} • ${date(s.at)}</p><span class="tag ${s.returned?'red':''}">${s.returned?'مرتجعة بالكامل':'فاتورة تجريبية'}</span></div><table><thead><tr><th>الصنف</th><th>الكمية</th><th>القيمة</th></tr></thead><tbody>${s.lines.map(l=>`<tr><td>${esc(l.name)}</td><td>${num(l.qty)} ${l.unit}</td><td>${money(E.amount(l.price,l.qty))}</td></tr>`).join('')}</tbody></table><div class="sum-row"><span>قبل الخصم</span><b>${money(s.subtotal)}</b></div><div class="sum-row"><span>الخصم</span><b>${money(s.discount)}</b></div><div class="receipt-total">الإجمالي ${money(s.total)} ج.م</div><div class="sum-row"><span>${s.method==='cash'?'نقدي':'بطاقة'}</span><span>الباقي ${money(s.received-s.total)}</span></div><p style="text-align:center;margin-top:18px">${esc(state.store.receiptNote)}</p></div>`,'طباعة الفاتورة',()=>{document.body.classList.add('printing-receipt');window.print();});}
function adjust(id){show('تسجيل الجرد الفعلي',`<p class="modal-desc">أدخل الكمية التي عدَدتها فعليًا. سيُسجّل الفرق وسببه في سجل العمليات.</p><div class="info-grid">${selectField('الصنف','product',state.products,id||state.products[0]?.id)}${field('الكمية الفعلية','actual','number',id?state.products.find(p=>p.id===id).stock:0,true,'min="0" step=".001"')}${field('سبب الفرق أو ملاحظة الجرد','reason','text','',true,'maxlength="150"')}</div>`,'اعتماد الجرد',f=>{const p=state.products.find(p=>p.id===f.get('product')),actual=E.quantity(f.get('actual')),reason=f.get('reason').trim();if(!Number.isFinite(actual)||actual<0||p.unit==='قطعة'&&!Number.isInteger(actual))throw Error('الكمية الفعلية غير صالحة');if(!reason)throw Error('اكتب سبب الجرد');const diff=E.quantity(actual-p.stock);if(mutate(s=>{s.products.find(x=>x.id===p.id).stock=actual;},'جرد مخزون',p.name+' • فرق '+diff+' '+p.unit+' • '+reason)){refresh();toast('تم تسجيل الجرد والفرق');}});}
function purchase(){if(!state.products.length)return;show('استلام بضاعة',`<div class="info-grid">${selectField('الصنف','product',state.products)}${selectField('المورد','supplier',state.contacts.filter(c=>c.type==='مورد').map(c=>c.name).concat('مورد نقدي'))}${field('الكمية المستلمة','qty','number',1,true,'min=".001" step=".001"')}${field('تكلفة الوحدة (ج.م)','cost','number',state.products[0].cost/100,true,'min="0" step=".01"')}</div><p class="help" style="margin-top:15px">تُضاف الكمية للمخزون؛ هذه التجربة تستبدل التكلفة الحالية بتكلفة هذا الاستلام.</p>`,'تسجيل الاستلام',f=>{const p=state.products.find(p=>p.id===f.get('product')),q=qty(f.get('qty'),p),cost=cents(f.get('cost'));if(mutate(s=>{const item=s.products.find(x=>x.id===p.id);item.stock=E.quantity(item.stock+q);item.cost=cost;s.purchases.push({id:uid('PUR'),at:stamp(),productId:p.id,name:p.name,qty:q,cost,total:E.amount(cost,q),supplier:f.get('supplier')});},'استلام بضاعة',p.name+' • '+q+' '+p.unit)){refresh();toast('تم الاستلام وتحديث المخزون');}});$('#modal select[name=product]').onchange=e=>{$('#modal input[name=cost]').value=state.products.find(p=>p.id===e.target.value).cost/100;};}
function hold(){if(!cart.length)return;if(mutate(s=>s.held.push({id:uid('HOLD'),at:stamp(),lines:cart,discount,method}),'تعليق فاتورة',cart.length+' أصناف')){cart=[];discount=0;render();toast('تم تعليق الفاتورة');}}
function held(){show('الفواتير المعلقة',state.held.length?state.held.map(h=>`<div class="list-row"><div><p>${esc(h.id)}</p><small>${date(h.at)} • ${num(h.lines.length)} أصناف</small></div><button type="button" class="btn soft" data-resume="${h.id}">استئناف</button></div>`).join(''):empty('لا توجد فواتير معلقة.','pause'),'إغلاق',close);}
function expense(){if(!state.shift.open){toast('افتح وردية لتسجيل مصروف نقدي',true);return;}show('تسجيل مصروف',`<div class="info-grid">${field('وصف المصروف','name','text','',true,'maxlength="100"')}${field('القيمة (ج.م)','amount','number','',true,'min=".01" step=".01"')}</div><p class="help" style="margin-top:14px">يخصم المصروف من نقدية الوردية ومن صافي الربح التقديري.</p>`,'تسجيل المصروف',f=>{const amount=cents(f.get('amount')),name=f.get('name').trim();if(amount<=0||!name)throw Error('الوصف والقيمة الموجبة مطلوبان');if(amount>E.expectedCash(state))throw Error('المصروف أكبر من النقدية المتوقعة بالدرج');if(mutate(s=>s.expenses.push({id:uid('EXP'),at:stamp(),name,amount,shiftId:s.shift.id}),'مصروف نقدي',name+' • '+money(amount)+' ج.م')){refresh();toast('تم تسجيل المصروف');}});}
function contact(){show('إضافة جهة اتصال',`<div class="info-grid">${field('الاسم','name','text','',true,'maxlength="100"')}${selectField('النوع','type',['عميل','مورد'])}${field('الهاتف','phone','tel','',false,'maxlength="30"')}</div>`,'حفظ الجهة',f=>{const name=f.get('name').trim();if(!name)throw Error('اكتب الاسم');if(mutate(s=>s.contacts.push({id:uid('C'),name,type:f.get('type'),phone:f.get('phone').trim()}),'إضافة جهة',name)){refresh();toast('تم حفظ الجهة');}});}
function closeShift(){if(cart.length){toast('أتمم أو علّق الفاتورة الحالية قبل إغلاق الوردية',true);return;}const expected=E.expectedCash(state);show('إغلاق الوردية',`<p class="modal-desc">عدّ النقدية الموجودة فعليًا في الدرج. الفرق سيظهر في سجل الوردية.</p><div class="callout">النقدية المتوقعة: <b>${money(expected)} ج.م</b></div>${field('النقدية الفعلية (ج.م)','actual','number',expected/100,true,'min="0" step=".01"')}${field('ملاحظة الإغلاق','note','text','',false,'maxlength="150"')}`,'إغلاق وتسجيل الفرق',f=>{const actual=cents(f.get('actual'));if(mutate(s=>{s.shiftHistory.push({...s.shift,closedAt:stamp(),expected,actual,difference:actual-expected,note:f.get('note').trim()});s.shift.open=false;},'إغلاق وردية','فرق الدرج '+money(actual-expected)+' ج.م')){refresh();toast('تم إغلاق الوردية');}});}
function openShift(){show('فتح وردية جديدة',`<div class="info-grid">${field('اسم الكاشير','cashier','text',state.shift.cashier,true,'maxlength="80"')}${field('اسم نقطة البيع','till','text',state.shift.till,true,'maxlength="40"')}${field('رصيد افتتاحي (ج.م)','opening','number',0,true,'min="0" step=".01"')}</div>`,'فتح الوردية',f=>{const cashier=f.get('cashier').trim(),till=f.get('till').trim(),opening=cents(f.get('opening'));if(!cashier||!till)throw Error('اكتب الكاشير ونقطة البيع');if(mutate(s=>s.shift={id:uid('SHIFT'),open:true,cashier,till,opening,startedAt:stamp()},'فتح وردية',cashier+' • '+money(opening)+' ج.م')){refresh();toast('تم فتح الوردية');}});}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function csv(name,rows){const safe=v=>{let text=String(v??'');if(/^[=+\-@\t\r]/.test(text))text="'"+text;return '"'+text.replaceAll('"','""')+'"';};download(name,'\uFEFF'+rows.map(r=>r.map(safe).join(',')).join('\r\n'),'text/csv;charset=utf-8');}
function validateBackup(s){
 if(!s||s.version!==1||!s.store||!s.shift||!Array.isArray(s.products)||s.products.length>10000)throw Error('صيغة النسخة غير صالحة');
 const strings=(o,keys)=>keys.forEach(k=>{if(typeof o[k]!=='string'||o[k].length>500)throw Error('حقل نصي غير صالح: '+k);});
 strings(s.store,['name','branch','address','phone','receiptNote']);strings(s.shift,['id','cashier','till','startedAt']);
 if(typeof s.shift.open!=='boolean'||!Number.isInteger(s.shift.opening)||s.shift.opening<0)throw Error('بيانات الوردية غير صالحة');
 const ids=new Set(),codes=new Set();
 s.products.forEach(p=>{strings(p,['id','name','brand','barcode','category','unit','expiry','art','color']);if(ids.has(p.id)||codes.has(p.barcode))throw Error('تكرار في الأصناف');ids.add(p.id);codes.add(p.barcode);if(!['قطعة','كجم'].includes(p.unit)||!/^#[0-9a-fA-F]{6}$/.test(p.color)||!['milk','oil','water','bag','cup','jar','cheese','perfume'].includes(p.art))throw Error('بيانات الصنف غير صالحة');for(const k of ['price','cost'])if(!Number.isInteger(p[k])||p[k]<0)throw Error('سعر غير صالح');for(const k of ['stock','min'])if(!Number.isFinite(p[k])||p[k]<0||E.quantity(p[k])!==p[k]||p.unit==='قطعة'&&!Number.isInteger(p[k]))throw Error('كمية غير صالحة');});
 for(const k of ['sales','purchases','expenses','held','contacts','audit','shiftHistory'])if(!Array.isArray(s[k])||s[k].length>50000)throw Error('قائمة غير صالحة: '+k);
 s.sales.forEach(x=>{strings(x,['id','at','shiftId']);if(!['cash','card'].includes(x.method)||typeof x.returned!=='boolean'||!Array.isArray(x.lines)||!x.lines.length)throw Error('فاتورة غير صالحة');x.lines.forEach(l=>{strings(l,['id','name','unit']);if(!ids.has(l.id)||!Number.isFinite(l.qty)||l.qty<=0||!Number.isInteger(l.price)||l.price<0||!Number.isInteger(l.cost)||l.cost<0)throw Error('سطر فاتورة غير صالح');});const t=E.totals(x.lines,x.discount);for(const k of ['subtotal','total','cost','grossProfit'])if(t[k]!==x[k])throw Error('إجماليات فاتورة غير متطابقة');if(!Number.isInteger(x.received)||x.received<x.total)throw Error('مدفوع غير صالح');if(x.returned){strings(x,['returnedAt','returnShiftId']);}});
 s.expenses.forEach(e=>{strings(e,['id','at','name','shiftId']);if(!Number.isInteger(e.amount)||e.amount<=0)throw Error('مصروف غير صالح');});
 s.contacts.forEach(c=>{strings(c,['id','name','type','phone']);if(!['عميل','مورد'].includes(c.type))throw Error('جهة غير صالحة');});
 s.audit.forEach(a=>strings(a,['at','event','detail']));
 s.purchases.forEach(p=>{strings(p,['id','at','productId','name','supplier']);if(!ids.has(p.productId)||!Number.isFinite(p.qty)||p.qty<=0||!Number.isInteger(p.cost)||p.cost<0||p.total!==E.amount(p.cost,p.qty))throw Error('استلام غير صالح');});
 s.held.forEach(h=>{strings(h,['id','at']);if(!Array.isArray(h.lines))throw Error('فاتورة معلقة غير صالحة');E.totals(h.lines,h.discount);h.lines.forEach(l=>{strings(l,['id','name','unit']);if(!ids.has(l.id)||!Number.isFinite(l.qty)||l.qty<=0||!Number.isInteger(l.price)||l.price<0||!Number.isInteger(l.cost)||l.cost<0)throw Error('سطر معلق غير صالح');});});
 s.shiftHistory.forEach(h=>{strings(h,['id','cashier','till','startedAt','closedAt','note']);for(const k of ['opening','expected','actual','difference'])if(!Number.isInteger(h[k]))throw Error('سجل وردية غير صالح');});
}
function restore(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{if(input.files[0].size>10*1024*1024)throw Error('الحد الأقصى ١٠ ميجابايت');const candidate=JSON.parse(await input.files[0].text());validateBackup(candidate);show('استعادة بيانات التجربة','<p class="modal-desc">سيتم استبدال بيانات هذا المتصفح بالنسخة المختارة. صدّر بياناتك الحالية إذا أردت الاحتفاظ بها.</p>','استبدال واستعادة',()=>{if(commit(candidate)){cart=[];discount=0;refresh();toast('تمت استعادة البيانات');}});}catch(e){toast('تعذر الاستيراد: '+e.message,true);}};input.click();}
function navigate(id){page=id;tableQuery='';tableFilter='الكل';render();window.scrollTo(0,0);}
document.addEventListener('click',e=>{
 const b=e.target.closest('button');if(!b)return;
 try{
 if(b.dataset.page){navigate(b.dataset.page);return;}
 if(b.dataset.category){category=b.dataset.category;document.querySelectorAll('[data-category]').forEach(x=>x.classList.toggle('selected',x===b));renderCatalog();return;}
 if(b.dataset.add){const p=state.products.find(x=>x.id===b.dataset.add);p.unit==='كجم'?changeQuantity(p.id):add(p.id);return;}
 if(b.dataset.remove){cart=cart.filter(l=>l.id!==b.dataset.remove);renderCart();return;}
 if(b.dataset.qty){const line=cart.find(l=>l.id===b.dataset.qty),p=state.products.find(p=>p.id===line.id),delta=Number(b.dataset.delta)*(p.unit==='كجم'?.25:1),next=E.quantity(line.qty+delta);if(next<=0)cart=cart.filter(l=>l.id!==line.id);else if(next<=p.stock)line.qty=next;else toast('المخزون غير كافٍ',true);renderCart();return;}
 if(b.dataset.weight){changeQuantity(b.dataset.weight);return;}
 if(b.dataset.method){method=b.dataset.method;renderCart();return;}
 if(b.dataset.edit){productForm(b.dataset.edit);return;}
 if(b.dataset.adjust){adjust(b.dataset.adjust);return;}
 if(b.dataset.receipt){receipt(b.dataset.receipt);return;}
 if(b.dataset.refund){const id=b.dataset.refund,s=state.sales.find(s=>s.id===id);show('مرتجع كامل',`<p class="modal-desc">ستُعاد كل أصناف الفاتورة ${esc(id)} إلى المخزون، وتُسجّل إعادة مبلغ ${money(s.total)} ج.م بنفس وسيلة الدفع. المرتجع الجزئي ضمن خطة التنفيذ.</p>`,'اعتماد المرتجع',()=>{const next=E.refund(state,id,stamp());if(commit(next)){refresh();toast('تم تسجيل المرتجع وإعادة المخزون');}});return;}
 if(b.dataset.resume){if(cart.length){toast('علّق أو أفرغ الفاتورة الحالية قبل الاستئناف',true);return;}const held=state.held.find(h=>h.id===b.dataset.resume);const lines=held.lines.map(l=>{const p=state.products.find(p=>p.id===l.id);return {...l,name:p.name,unit:p.unit,price:p.price,cost:p.cost};});E.validateLines(state.products,lines);E.totals(lines,held.discount);if(mutate(s=>s.held=s.held.filter(h=>h.id!==held.id),'استئناف فاتورة',held.id)){cart=lines;discount=held.discount;method=held.method;close();render();toast('تم الاستئناف بالأسعار الحالية');}return;}
 const a=b.dataset.action;if(!a)return;
 if(a.startsWith('goto-')){navigate(a.slice(5));return;}
 const actions={pay,hold,held,'close-modal':close,'add-product':()=>productForm(),adjust:()=>adjust(),purchase,contact,expense,'close-shift':closeShift,'open-shift':openShift,backup:()=>download('nabta-backup-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify(state,null,2),'application/json'),restore,
 clear:()=>{if(!cart.length)return;show('إفراغ الفاتورة','<p class="modal-desc">حذف الأصناف من الفاتورة الحالية؟ لن يتغير المخزون.</p>','إفراغ',()=>{cart=[];discount=0;close();renderCart();});},
 reset:()=>show('إعادة ضبط التجربة','<p class="modal-desc">سيتم حذف تعديلات التجربة في هذا المتصفح والعودة إلى بيانات العرض الأصلية.</p>','إعادة ضبط',()=>{if(commit(seed())){cart=[];discount=0;refresh();toast('تمت إعادة ضبط التجربة');}}),
 'expiry-filter':()=>{page='inventory';tableQuery='';tableFilter='قرب الصلاحية';render();},
 'save-settings':()=>{const form=$('#settings-form');if(!form.reportValidity())return;const f=new FormData(form);const name=f.get('name').trim(),branch=f.get('branch').trim();if(!name||!branch){toast('اكتب اسم المتجر والفرع',true);return;}if(mutate(s=>s.store={name,branch,address:f.get('address').trim(),phone:f.get('phone').trim(),receiptNote:f.get('receiptNote').trim()},'تعديل الإعدادات',name)){render();toast('تم حفظ بيانات المتجر');}},
 'export-products':()=>csv('nabta-products.csv',[['الاسم','الباركود','التصنيف','الوحدة','سعر البيع ج.م','التكلفة ج.م','المخزون','حد الطلب','الصلاحية'],...state.products.map(p=>[p.name,p.barcode,p.category,p.unit,p.price/100,p.cost/100,p.stock,p.min,p.expiry])]),
 'export-sales':()=>csv('nabta-sales.csv',[['الفاتورة','التاريخ','الإجمالي ج.م','التكلفة ج.م','الخصم ج.م','الدفع','الحالة'],...state.sales.map(s=>[s.id,s.at,s.total/100,s.cost/100,s.discount/100,s.method,s.returned?'مرتجعة':'مكتملة'])]),
 help:()=>show('عن هذه النسخة','<div class="callout warn">هذه واجهة تفاعلية للتجربة والتسليم للمطور. لا تستخدمها وحدها لحفظ حسابات متجر فعلي.</div><p class="modal-desc">الأرقام التجريبية قابلة للتعديل وتُحفظ في متصفحك. لا توجد صلاحيات حقيقية أو ربط بين الأجهزة أو فواتير ضريبية أو مزامنة بنكية. وثيقة كوديكس المرفقة تحدد تنفيذ هذه المزايا.</p>','فهمت',close)};
 if(actions[a])actions[a]();
 }catch(err){toast(err.message,true);}
});
document.addEventListener('input',e=>{if(e.target.id==='pos-search'){query=e.target.value.trim();renderCatalog();}if(e.target.id==='table-search'){tableQuery=e.target.value.trim();$('#table-results').innerHTML=page==='products'?productTable():page==='inventory'?inventoryTable():contactsTable();}});
document.addEventListener('change',e=>{if(e.target.id==='table-filter'){tableFilter=e.target.value;$('#table-results').innerHTML=page==='products'?productTable():page==='inventory'?inventoryTable():contactsTable();}if(e.target.id==='discount'){try{const next=cents(e.target.value);E.totals(cart,next);discount=next;}catch(err){toast(err.message,true);}renderCart();}});
document.addEventListener('keydown',e=>{if($('#modal').open)return;if(page==='pos'&&e.key==='Enter'&&e.target.id==='pos-search'){e.preventDefault();const p=state.products.find(p=>p.barcode===e.target.value.trim());if(p){p.unit==='كجم'?changeQuantity(p.id):add(p.id);query='';e.target.value='';renderCatalog();}else toast('الباركود غير مسجل. أضف الصنف أولًا.',true);}if(e.key==='F2'){e.preventDefault();if(page!=='pos')navigate('pos');$('#pos-search').focus();$('#pos-search').select();}if(page==='pos'&&e.key==='F4'){e.preventDefault();$('#discount')?.blur();pay();}if(page==='pos'&&e.key==='F8'){e.preventDefault();$('#discount')?.blur();hold();}});
window.addEventListener('afterprint',()=>document.body.classList.remove('printing-receipt'));
$('#modal').addEventListener('close',()=>document.body.classList.remove('printing-receipt'));
window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue){toast('البيانات تغيّرت في نافذة أخرى. أعد تحميل الصفحة قبل متابعة العمل.',true);document.querySelectorAll('button').forEach(b=>b.disabled=true);}});
render();if(startupWarning)toast(startupWarning,true);
})();
